/**
 * Registry of printable blank maps (/maps/blank/<slug>/).
 *
 * One entry here = one map page, its four SVG variants (generated by
 * scripts/build-blank-maps.mjs into public/maps/blank/) and a sitemap URL.
 * Like tools.ts, there is no second place to register a map.
 *
 * The generator reads the `build` block; pages read everything else plus the
 * generated facts in src/data/blank-maps.json (unit names, areas, populations),
 * so every number on a map page comes from the boundary or Census file itself.
 */

export type BlankMapKind = "world" | "continent" | "us" | "us-state" | "country";

export interface BlankMapBuild {
  /** Natural Earth ADM0_A3 code (country maps) or Census state FIPS (US states). */
  code?: string;
  /** Country maps: merge Natural Earth admin-1 units into a parent field. */
  dissolve?: "region" | "geonunit";
  /** Unit names (after renames) or Natural Earth type_en values to leave off the map. */
  exclude?: string[];
  /** Natural Earth name -> name shown on the map. */
  rename?: Record<string, string>;
  /** Merge one unit into another: shown name -> name it joins. */
  merge?: Record<string, string>;
  /** Continent maps: Natural Earth CONTINENT value(s). */
  continents?: string[];
  /** lon/lat box to clip to: [west, south, east, north]. */
  clip?: [number, number, number, number];
  /** Projection override (proj4 string or a mapshaper alias). Default: Lambert azimuthal equal-area at the centre. */
  proj?: string;
}

export interface BlankMap {
  slug: string;
  /** "Texas", "France", "Europe". */
  name: string;
  kind: BlankMapKind;
  /** Plural noun for the shapes drawn: "counties", "regions", "countries". */
  units: string;
  /** Singular of `units`. */
  unit: string;
  /** Known gaps between the source boundaries and today's divisions. Shown on the page. */
  note?: string;
  build: BlankMapBuild;
}

const NE_LAG =
  "Natural Earth's admin-1 layer can lag behind recent reorganisations.";

const state = (slug: string, name: string, fips: string, units = "counties", unit = "county", note?: string): BlankMap => ({
  slug,
  name,
  kind: "us-state",
  units,
  unit,
  note,
  build: { code: fips },
});

const country = (
  slug: string,
  name: string,
  code: string,
  units: string,
  unit: string,
  build: Omit<BlankMapBuild, "code"> = {},
  note?: string,
): BlankMap => ({ slug, name, kind: "country", units, unit, note, build: { code, ...build } });

