export function blankMapBySlug(slug: string): BlankMap | undefined {
  return blankMaps.find((m) => m.slug === slug);
}

export const blankMapGroups: { label: string; kinds: BlankMapKind[] }[] = [
  { label: "World and continents", kinds: ["world", "continent"] },
  { label: "United States", kinds: ["us", "us-state"] },
  { label: "Countries", kinds: ["country"] },
];
